═════════ ZimmProductName test — how does it assert the heading? ═════════
     1	/**
     2	 * Scoped to this atom's own contract per testing.md: given a name or an empty one, does it render
     3	 * the right branch.
     4	 *
     5	 * The heading level is deliberately not re-asserted here — `index.stories.tsx`'s `Default` and
     6	 * `HeadingLevels` plays already pin the role and level for all three `as` values, and duplicating
     7	 * that at this layer would be the cross-layer duplication testing.md rules out. What no other
     8	 * layer covers is the empty-name branch: `ZimmProductContent`'s stories always pass a real name,
     9	 * and the page's own mapper short-circuits before this atom is reached, so nothing else proves
    10	 * this atom collapses rather than rendering an empty heading.
    11	 */
    12	import React from 'react';
    13	import { describe, test, expect } from 'vitest';
    14	import { render, screen } from '@testing-library/react';
    15	import { ZimmProductName } from './index';
    16	
    17	describe('ZimmProductName', () => {
    18	  test('renders the name it is handed', () => {
    19	    render(<ZimmProductName name="Natura Long Sleeve Linen Mini Dress" as="h2" />);
    20	    expect(screen.getByTestId('product-name').textContent).toBe('Natura Long Sleeve Linen Mini Dress');
    21	  });
    22	
    23	  test('renders nothing for an empty name', () => {
    24	    const { container } = render(<ZimmProductName name="" as="h2" />);
    25	
    26	    // `name` is typed `string`, so TypeScript rules out an absent name but not an empty one. An
    27	    // empty `heading3` node is not free: it keeps its row in `ZimmProductContent`'s flex column
    28	    // and consumes the column's 20px `gap`, leaving a visible hole above the price.
    29	    //
    30	    // Asserted as an empty container rather than an absent testid, for the same reason
    31	    // `zimmProductPrice/index.test.tsx` does it: a node that still carried the recipe's styling
    32	    // but had lost its `data-testid` would satisfy the narrower check while being precisely the
    33	    // gap-consuming element this guard exists to prevent.
    34	    expect(container).toBeEmptyDOMElement();
    35	  });
    36	});

